<template><app-layout>
  <template #header><div><h2 class="font-semibold text-xl text-gray-800">EIR Accounting Rules</h2><p class="mt-1 text-sm text-gray-600">Approved rules that suggest whether an imported fee or cost forms part of the EIR</p></div></template>
  <template #actions><button @click="openCreate" class="primary-btn">Create rule</button></template>
  <div class="w-full space-y-6">
    <div class="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      <div class="px-5 py-4 border-b"><h3 class="font-semibold text-gray-900">Rule register</h3><p class="text-xs text-gray-500">{{ rules.length }} rule(s), {{ rules.filter(r => r.status === 'APPROVED').length }} approved, {{ rules.filter(r => r.status === 'PROPOSED' || r.approval_to_confirm || r.proposed_active !== null).length }} awaiting a second person. Approving a rule, and switching it on or off, needs a reason and a person other than the one who proposed it. The lowest priority number is tried first. Rules only suggest: every imported line stays pending until it is classified and reviewed by someone else.</p></div>
      <div class="overflow-x-auto"><table class="min-w-full divide-y divide-gray-200"><thead><tr><th v-for="h in ['Priority / rule','Matching criteria','Treatment','Approval','Actions']" :key="h" class="th">{{h}}</th></tr></thead><tbody class="divide-y">
        <tr v-for="r in pagedRules" :key="r.id" class="hover:bg-maiic-50"><td class="td"><div class="font-medium">{{r.priority}} · {{r.name}}</div><span :class="r.active?'badge-green':'badge-gray'">{{r.active?'Active':'Inactive'}}</span></td><td class="td text-sm text-gray-600"><div>Type: {{r.fee_type||'any'}}</div><div>Description: {{r.description_contains||'any'}}</div><div>Direction: {{r.cashflow_direction||'either'}} · GL: {{r.gl_account_ref||'any'}}</div></td><td class="td"><span :class="r.proposed_integral?'badge-green':'badge-gray'">{{r.proposed_integral?'Integral':'Non-integral'}}</span><p class="text-xs text-gray-500 mt-1 max-w-xs">{{r.rationale}}</p></td><td class="td"><span :class="statusBadge(r)">{{statusLabel(r)}}</span><div class="text-xs text-gray-500">{{r.approver?.name||''}}</div><div v-if="r.approval_reason" class="text-xs text-gray-400 max-w-[14rem]">{{r.approval_reason}}</div><div v-if="r.proposed_active !== null" class="mt-1"><span class="badge-yellow">Switch {{r.proposed_active?'on':'off'}} proposed</span><div class="text-xs text-gray-400 max-w-[14rem]">{{r.switch_reason}}</div></div></td><td class="td whitespace-nowrap"><div class="flex flex-wrap items-center gap-1.5"><button type="button" @click="edit(r)" class="maiic-action maiic-action-edit" title="Edit rule (proposes it again)"><font-awesome-icon icon="pen" /></button><button v-if="canDecide(r.status==='PROPOSED' || r.approval_to_confirm, makerOf(r))" type="button" @click="decide(r,'approve')" class="maiic-action maiic-action-view" :title="r.approval_to_confirm?'Confirm the approval':'Approve rule'"><font-awesome-icon icon="check" /></button><button v-if="r.status==='PROPOSED'" type="button" @click="decide(r,'reject')" class="maiic-action maiic-action-neutral" title="Reject rule"><font-awesome-icon icon="times" /></button><button v-if="r.status==='PROPOSED' && (makerOf(r)===null || makerOf(r)===userId)" type="button" @click="decide(r,'withdraw')" class="maiic-action maiic-action-neutral" title="Withdraw rule"><font-awesome-icon icon="trash" /></button><button v-if="r.proposed_active===null" type="button" @click="decide(r,'propose_switch')" class="maiic-action maiic-action-neutral" :title="r.active?'Propose switching the rule off':'Propose switching the rule on'"><font-awesome-icon icon="exchange-alt" /></button><template v-else><button v-if="canDecide(true, r.switch_proposed_by)" type="button" @click="decide(r,'approve_switch')" class="maiic-action maiic-action-view" title="Approve the switch"><font-awesome-icon icon="check" /></button><button type="button" @click="decide(r,'reject_switch')" class="maiic-action maiic-action-neutral" title="Reject the switch"><font-awesome-icon icon="times" /></button></template></div></td></tr>
        <tr v-if="!rules.length"><td colspan="5" class="p-10 text-center text-sm text-gray-500">No rules created yet. Use <strong>Create rule</strong> at the top right to add the first one.</td></tr>
      </tbody></table></div>
      <div v-if="rules.length > 15" class="border-t border-gray-100 px-4 py-3"><ClientPager v-model="page" :total="rules.length"/></div>
    </div>
  </div>
  <jet-dialog-modal :show="showModal" max-width="2xl" @close="closeModal"><template #title><div><div class="font-semibold text-gray-900">{{editingId?'Edit accounting rule':'Create accounting rule'}}</div><p class="mt-1 text-sm font-normal text-gray-500">Define the conditions and suggested IFRS 9 treatment.</p></div></template><template #content>
    <div class="rounded-md border border-gray-200 bg-gray-50 p-4 mb-5"><h4 class="text-xs font-semibold uppercase tracking-wide text-gray-500 mb-3">Rule identity</h4><div class="grid grid-cols-1 sm:grid-cols-3 gap-4"><label class="field sm:col-span-2">Rule name<input v-model="form.name" class="form-input mt-1" placeholder="e.g. Direct arrangement fees"></label><label class="field">Priority<input v-model.number="form.priority" type="number" min="1" class="form-input mt-1"></label></div></div>
    <h4 class="text-xs font-semibold uppercase tracking-wide text-gray-500 mb-3">Matching conditions</h4><p class="text-xs text-gray-500 mb-3">Blank conditions match any value.</p><div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <label class="field">Fee/cost type<select v-model="form.fee_type" class="form-input mt-1"><option value="">Any type</option><option v-for="t in feeTypes" :key="t" :value="t">{{t}}</option></select></label><label class="field">Description contains<input v-model="form.description_contains" class="form-input mt-1"></label><label class="field">GL account<input v-model="form.gl_account_ref" class="form-input mt-1"></label>
      <label class="field">Cash direction<select v-model="form.cashflow_direction" class="form-input mt-1"><option value="">Either</option><option value="RECEIVED">Received by MAIIC</option><option value="PAID">Paid by MAIIC</option></select></label><label class="field">Proposed treatment<select v-model="form.proposed_integral" class="form-input mt-1"><option :value="true">Integral - include in EIR</option><option :value="false">Non-integral - exclude from EIR</option></select></label>
      <label class="field sm:col-span-2">Accounting rationale<textarea v-model="form.rationale" rows="3" class="form-input mt-1" placeholder="Explain why this treatment is appropriate"></textarea></label><label class="sm:col-span-2 inline-flex items-center text-sm text-gray-700"><input v-model="form.active" type="checkbox" class="rounded border-gray-300 text-maiic-600 mr-2">Active once a second person approves it</label>
    </div><div v-if="Object.keys(errors).length" class="mt-4 rounded-md bg-red-50 border border-red-200 px-3 py-2 text-sm text-red-700">{{Object.values(errors)[0]}}</div>
  </template><template #footer><button @click="closeModal" class="secondary-btn mr-2">Cancel</button><button @click="save" :disabled="processing" class="primary-btn">{{processing?'Saving...':(editingId?'Update rule':'Create rule')}}</button></template></jet-dialog-modal>
  <jet-dialog-modal :show="decision.show" max-width="lg" @close="decision.show=false"><template #title><div class="font-semibold text-gray-900">{{decisionTitle}}</div><p class="mt-1 text-sm font-normal text-gray-500">{{decision.rule?.name}}</p></template><template #content>
    <label class="field">Reason (at least 10 characters)<textarea v-model="decision.reason" rows="3" class="form-input mt-1" placeholder="The policy reference, the evidence, or what changed"></textarea></label>
    <p v-if="uatMode && selfDecision" class="mt-2 text-xs text-amber-700">UAT mode: you are deciding your own proposal; it is recorded on the self-approvals report.</p>
  </template><template #footer><button @click="decision.show=false" class="secondary-btn mr-2">Cancel</button><button @click="submitDecision" :disabled="processing || decision.reason.trim().length < 10" class="primary-btn">{{processing?'Saving...':'Confirm'}}</button></template></jet-dialog-modal>
  <teleport to="head"><title>EIR Accounting Rules</title></teleport>
</app-layout></template>
<script>
import AppLayout from '@/Layouts/AppLayout.vue'; import JetDialogModal from '@/Jetstream/DialogModal.vue'; import ClientPager from '@/Components/ClientPager.vue'
const blank=()=>({name:'',fee_type:'',description_contains:'',gl_account_ref:'',cashflow_direction:'',proposed_integral:true,rationale:'',priority:100,active:true})
export default{components:{AppLayout,JetDialogModal,ClientPager},props:{rules:Array,feeTypes:Array,userId:{type:Number,default:null},uatMode:{type:Boolean,default:false},errors:{type:Object,default:()=>({})}},data:()=>({page:1,showModal:false,editingId:null,processing:false,form:blank(),decision:{show:false,rule:null,action:'',reason:''}}),computed:{pagedRules(){return (this.rules||[]).slice((this.page-1)*15,this.page*15)},decisionTitle(){return {approve:'Approve the rule',reject:'Reject the rule',withdraw:'Withdraw the rule',propose_switch:this.decision.rule?.active?'Propose switching the rule off':'Propose switching the rule on',approve_switch:'Approve the switch',reject_switch:'Reject the switch'}[this.decision.action]||''},selfDecision(){const r=this.decision.rule;if(!r)return false;return this.decision.action==='approve'?this.makerOf(r)===this.userId:(this.decision.action==='approve_switch'?r.switch_proposed_by===this.userId:false)}},methods:{makerOf(r){return r.updated_by??r.created_by??null},canDecide(open,maker){return open&&(maker===null||maker!==this.userId||this.uatMode)},statusLabel(r){if(r.status==='APPROVED')return r.approval_to_confirm?'Approved, to be confirmed':'Approved';return {PROPOSED:'Awaiting approval',REJECTED:'Rejected',WITHDRAWN:'Withdrawn'}[r.status]||r.status},statusBadge(r){return r.status==='APPROVED'?(r.approval_to_confirm?'badge-yellow':'badge-green'):(r.status==='PROPOSED'?'badge-yellow':'badge-gray')},decide(r,action){this.decision={show:true,rule:r,action,reason:''}},submitDecision(){this.processing=true;this.$inertia.post(this.route('eir-accounting-rules.decide',this.decision.rule.id),{action:this.decision.action,reason:this.decision.reason},{onFinish:()=>{this.processing=false},onSuccess:()=>{this.decision.show=false}})},reset(){this.editingId=null;this.form=blank()},openCreate(){this.reset();this.showModal=true},closeModal(){if(!this.processing){this.showModal=false;this.reset()}},edit(r){this.editingId=r.id;this.form={name:r.name,fee_type:r.fee_type||'',description_contains:r.description_contains||'',gl_account_ref:r.gl_account_ref||'',cashflow_direction:r.cashflow_direction||'',proposed_integral:!!r.proposed_integral,rationale:r.rationale,priority:r.priority,active:!!r.active};this.showModal=true},save(){this.processing=true;const done=()=>this.processing=false,close=()=>{this.showModal=false;this.reset()};this.editingId?this.$inertia.put(this.route('eir-accounting-rules.update',this.editingId),this.form,{onFinish:done,onSuccess:close}):this.$inertia.post(this.route('eir-accounting-rules.store'),this.form,{onFinish:done,onSuccess:close})}}}
</script>
<style scoped>
.field{@apply block text-sm font-medium text-gray-700}
.form-input{@apply block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-maiic-500}
.action{@apply mr-3 text-sm text-maiic-700 hover:underline}
</style>
